<script setup lang="ts">
import {ref} from 'vue';import {onLoad,onShow} from '@dcloudio/uni-app';import {useI18n} from 'vue-i18n';import {api} from '@/api';import {managementGo,managementTime} from '@/shared/management';import {confirm} from '@ai-shop/ui/prompt';import {idempotencyKey} from '@shared/net/http-client';import type {Brand,ManagementResource,ManagementAudit} from '@/api/management-types';
const loaded=ref(false);
const {t}=useI18n();const b=ref('');const brand=ref<Brand|null>(null);const stores=ref<ManagementResource[]>([]);const audits=ref<ManagementAudit[]>([]);const next=ref<string|null>(null);const auditNext=ref<string|null>(null);const failed=ref(false),busy=ref(false);let key=idempotencyKey();
async function load(){failed.value=false;try{brand.value=await api.mBrand(b.value);const page=await api.mBrandStores(b.value);stores.value=page.items;next.value=page.nextCursor;if(brand.value.actions?.includes('brand.audit.read')){const result=await api.mBrandAudit(b.value);audits.value=result.items;auditNext.value=result.nextCursor}}catch{failed.value=true}finally{loaded.value=true}}
async function more(audit=false){try{if(audit){const p=await api.mBrandAudit(b.value,auditNext.value||undefined);audits.value.push(...p.items);auditNext.value=p.nextCursor}else{const p=await api.mBrandStores(b.value,next.value||undefined);stores.value.push(...p.items);next.value=p.nextCursor}}catch{failed.value=true}}
async function toggle(){if(busy.value||!brand.value)return;const active=brand.value.status==='ACTIVE';if(!await confirm({title:t(active?'management.stopBrand':'management.enableBrand'),danger:active}))return;busy.value=true;try{await api.mBrandStatus(b.value,{targetStatus:active?'INACTIVE':'ACTIVE',expectedRevision:brand.value.revision,reason:t(active?'management.stopBrand':'management.enableBrand')},key);await load();key=idempotencyKey()}catch{failed.value=true}finally{busy.value=false}}
onLoad(q=>{b.value=q?.b||''});onShow(load);
</script>
<template><sh-scaffold title-key="management.brandDetail"><view v-if="failed" class="sh-card" @tap="load">{{t('management.retry')}}</view><template v-if="brand">
 <view class="sh-card"><text class="txt-title">{{brand.name}}</text><view class="sh-cell"><text class="sh-chip">{{t('management.state.'+brand.status)}}</text></view><sh-kv :label="t('management.createdAt')">{{managementTime(brand.createdAt)}}</sh-kv><sh-kv :label="t('management.updatedAt')">{{managementTime(brand.updatedAt)}}</sh-kv><sh-kv :label="t('management.updatedBy')">{{brand.updatedByLabel||'—'}}</sh-kv></view>
 <view class="sh-card"><text class="txt-strong">{{t('management.stores')}}</text><view v-for="store in stores" :key="store.storeNo" class="sh-cell sh-row sh-row--between" @tap="store.canConfigureBrand&&managementGo('store_brand',{m:brand.managementNo,s:store.storeNo})"><text>{{store.name}}</text><sh-go v-if="store.canConfigureBrand"/></view><sh-empty :pending="!loaded" v-if="!stores.length" bare :text="t('management.empty')"/><view v-if="next" class="sh-btn sh-btn--soft" @tap="more()">{{t('management.more')}}</view></view>
 <view v-if="brand.actions?.includes('sv.issuer.read')" role="button" class="sh-card sh-row sh-row--between sh-hit" @tap="managementGo('storedValueIssuer',{m:brand.managementNo,b:brand.brandNo})"><text class="txt-strong">{{t('management.brandStoredValue')}}</text><sh-go/></view>
 <view v-if="brand.actions?.includes('brand.audit.read')" class="sh-card"><text class="txt-strong">{{t('management.audit')}}</text><view v-for="(entry,i) in audits" :key="i" class="sh-cell"><text>{{t('management.auditAction.'+entry.action)}}</text><view class="txt-sub sh-muted">{{managementTime(entry.occurredAt)}}</view></view><view v-if="auditNext" class="sh-btn sh-btn--soft" @tap="more(true)">{{t('management.more')}}</view></view>
 <sh-actionbar v-if="brand.actions?.includes('brand.manage')"><view class="sh-row"><view class="sh-btn sh-btn--soft" @tap="managementGo('brand_edit',{b:brand.brandNo,m:brand.managementNo})">{{t('management.edit')}}</view><view class="sh-btn" :class="{'sh-btn--danger':brand.status==='ACTIVE'}" @tap="toggle">{{t(busy?'management.loading':brand.status==='ACTIVE'?'management.stopBrand':'management.enableBrand')}}</view></view></sh-actionbar>
 </template></sh-scaffold></template>
